use vstd::prelude::*;

verus! {

fn solve(t: Vec<char>) -> (out: Vec<char>)
    requires
        t.len() >= 1,
    ensures
        out.len() == t.len(),
        forall|i: int| 0 <= i < t.len() ==> out[i] == t[i],
{
    let n: usize = t.len();
    let mut out: Vec<char> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            n == t.len(),
            i <= n,
            out.len() == i,
            forall|k: int| 0 <= k < i ==> out[k] == t[k],
        decreases
            n - i,
    {
        // push the next character
        out.push(t[i]);

        // after the push, out.len() became i+1, and the new element matches
        assert(out[i as int] == t[i as int]);

        i = i + 1;
    }

    out
}

} // verus!

